mapper.select:
SELECT COUNT(*) FROM shopwizard.tCatCate C
WHERE C.SvcCode = #{svcCode} AND C.CateCode = #{cateCode}
  AND NOT EXISTS (SELECT 1 FROM shopwizard.tCatCate X WHERE X.SvcCode = C.SvcCode AND X.ParentCateCode = C.CateCode)

SELECT COUNT(*) FROM shopwizard.tCatProd
WHERE ShopProdCode = #{shopProdCode}
AND ProdCode <> #{exceptProdCode}
